class Solution {
public:
    bool canThreePartsEqualSum(vector<int>& arr) {
        int total = 0;
        for (int x : arr) total += x;
        if (total % 3) return false;
        int share = total / 3, run = 0, parts = 0;
        for (int i = 0; i < (int)arr.size(); i++) {
            run += arr[i];
            if (run == share && parts < 2) {
                parts++;
                run = 0;
            }
        }
        return parts == 2 && run == share;
    }
};
